python3 - <<'PY'
import zipfile, re
out='/root/training_feedback_ready.hwpx'
with zipfile.ZipFile(out,'r') as z:
    for name in sorted(z.namelist()):
        if name.lower().endswith('.xml'):
            txt=z.read(name).decode('utf-8')
            if '{{' in txt or '}}' in txt:
                print('PLACEHOLDER STILL IN', name)
            # check for any lineSegArray/linesegarray inside paragraphs that include replaced text patterns (approx)
            # We'll ensure that in section0 paragraphs 1-9 and section1 1-4, there is no linesegarray.
            if name.endswith('Contents/section0.xml'):
                # simplistic: ensure each replaced paragraph tag doesn't include linesegarray before </hp:p>
                for pid in range(1,10):
                    m=re.search(rf'(<hp:p\b[^>]*\bid="{pid}"[^>]*>.*?</hp:p>)', txt, re.DOTALL)
                    if not m:
                        print('Missing paragraph id', pid)
                        continue
                    blk=m.group(1)
                    if re.search(r'<hp:(?:lineSegArray|linesegarray)\b', blk):
                        print('Found lineSegArray in modified paragraph', pid)
            if name.endswith('Contents/section1.xml'):
                for pid in range(1,5):
                    m=re.search(rf'(<hp:p\b[^>]*\bid="{pid}"[^>]*>.*?</hp:p>)', txt, re.DOTALL)
                    if not m:
                        print('Missing paragraph id', pid)
                        continue
                    blk=m.group(1)
                    if re.search(r'<hp:(?:lineSegArray|linesegarray)\b', blk):
                        print('Found lineSegArray in modified paragraph', pid)
print('Done')
PY

